// Texte mit wechselnden Teilen. $1, $2 … stehen für die Fundstellen der Klammern; mit
// nested werden auch diese Teile übersetzt (etwa eine eingebettete Fehlermeldung).
export const PATTERNS = [
  { re: /^Zuletzt geprüft: (.+)$/, to: ['Last checked: $1', 'Dernière vérification : $1', 'Última comprobación: $1', 'Ultima verifica: $1'] },
  { re: /^Freischaltung fehlgeschlagen: (.+)$/, to: ['Activation failed: $1', 'L’activation a échoué : $1', 'La activación ha fallado: $1', 'Attivazione non riuscita: $1'] },
  { re: /^Empfohlen für dieses Publikum: (.+)$/, to: ['Recommended for this audience: $1', 'Recommandé pour ce public : $1', 'Recomendado para este público: $1', 'Consigliato per questo pubblico: $1'] },
  { re: /^Tempo am Anfang (\d+), am Ende (\d+) Wörter pro Minute$/, to: ['Pace at the start $1, at the end $2 words per minute', 'Rythme au début $1, à la fin $2 mots par minute', 'Ritmo al principio $1, al final $2 palabras por minuto', 'Ritmo all’inizio $1, alla fine $2 parole al minuto'] },
  { re: /^(.+) pro Minute$/, to: ['$1 per minute', '$1 par minute', '$1 por minuto', '$1 al minuto'] },
  { re: /^(\d+) Wörter$/, to: ['$1 words', '$1 mots', '$1 palabras', '$1 parole'] },
  { re: /^(\d+) Sek\.$/, to: ['$1 s', '$1 s', '$1 s', '$1 s'] },
  { re: /^entspricht (.+) pro Monat$/, to: ['equals $1 per month', 'soit $1 par mois', 'equivale a $1 al mes', 'pari a $1 al mese'] },
  { re: /^(.+) pro Monat$/, to: ['$1 per month', '$1 par mois', '$1 al mes', '$1 al mese'] },
  { re: /^(.+) pro Jahr$/, to: ['$1 per year', '$1 par an', '$1 al año', "$1 all'anno"] },
  { re: /^(\d+) % sparen$/, to: ['Save $1%', 'Économisez $1 %', 'Ahorra un $1 %', 'Risparmia il $1%'] },
  { re: /^(\d+) Wörter, ca\. (\d+) Min\.$/, to: ['$1 words, approx. $2 min', '$1 mots, env. $2 min', '$1 palabras, aprox. $2 min', '$1 parole, circa $2 min'] },
  { re: /^(\d+) Wörter, geändert (.+)$/, to: ['$1 words, changed $2', '$1 mots, modifié le $2', '$1 palabras, modificado el $2', '$1 parole, modificato il $2'] },
  { re: /^(.+) · (\d+) Wörter$/, to: ['$1 · $2 words', '$1 · $2 mots', '$1 · $2 palabras', '$1 · $2 parole'] },
  { re: /^(.+) · Rest ca\. (.+)$/, to: ['$1 · approx. $2 left', '$1 · reste env. $2', '$1 · quedan aprox. $2', '$1 · restano circa $2'] },
  { re: /^Lesezeile: (\d+) %$/, to: ['Reading line: $1%', 'Ligne de lecture : $1 %', 'Línea de lectura: $1 %', 'Riga di lettura: $1%'] },
  { re: /^Anzeigen: (\d+) an$/, to: ['Displays: $1 on', 'Affichages : $1 activés', 'Pantallas: $1 activadas', 'Schermi: $1 attivi'] },
  { re: /^gleich: (.+)$/, to: ['next: $1', 'ensuite : $1', 'a continuación: $1', 'tra poco: $1'] },
  { re: /^voraussichtlich \+(.+)$/, to: ['expected +$1', 'prévu +$1', 'previsto +$1', 'previsto +$1'] },
  { re: /^Kamera (\d+)$/, to: ['Camera $1', 'Caméra $1', 'Cámara $1', 'Videocamera $1'] },
  { re: /^Aufnahme gespeichert: (.+)$/, to: ['Recording saved: $1', 'Enregistrement sauvegardé : $1', 'Grabación guardada: $1', 'Registrazione salvata: $1'] },
  { re: /^Kamera: (\w+)$/, to: ['Camera: $1', 'Caméra : $1', 'Cámara: $1', 'Videocamera: $1'] },
  { re: /^Mikrofon (\d+)$/, to: ['Microphone $1', 'Microphone $1', 'Micrófono $1', 'Microfono $1'] },
  { re: /^Dateityp \.(\w+) wird nicht unterstützt\.$/, to: ['File type .$1 is not supported.', "Le type de fichier .$1 n'est pas pris en charge.", 'El tipo de archivo .$1 no es compatible.', 'Il tipo di file .$1 non è supportato.'] },
  { re: /^„(.+)" wird gelesen …$/, to: ['Reading “$1” …', 'Lecture de « $1 » …', 'Leyendo «$1» …', 'Lettura di «$1» …'] },
  { re: /^Gespeichert als „(.+)" im Ordner „(.+)"\.$/, to: ['Saved as “$1” in the folder “$2”.', 'Enregistré sous « $1 » dans le dossier « $2 ».', 'Guardado como «$1» en la carpeta «$2».', 'Salvato come «$1» nella cartella «$2».'] },
  { re: /^Gespeichert als „(.+)"\.$/, to: ['Saved as “$1”.', 'Enregistré sous « $1 ».', 'Guardado como «$1».', 'Salvato come «$1».'] },
  { re: /^Ordner „(.+)" auflösen\? Die Skripte darin bleiben erhalten\.$/, to: ['Dissolve the folder “$1”? The scripts in it are kept.', 'Dissoudre le dossier « $1 » ? Les scripts qu’il contient sont conservés.', '¿Disolver la carpeta «$1»? Los guiones que contiene se conservan.', 'Sciogliere la cartella «$1»? I copioni al suo interno restano.'] },
  { re: /^Ordner (.+) auflösen$/, to: ['Dissolve folder $1', 'Dissoudre le dossier $1', 'Disolver la carpeta $1', 'Sciogli la cartella $1'] },
  { re: /^Skript „(.+)" mit allen Versionen endgültig löschen\?$/, to: ['Permanently delete the script “$1” with all its versions?', 'Supprimer définitivement le script « $1 » avec toutes ses versions ?', '¿Borrar definitivamente el guion «$1» con todas sus versiones?', 'Eliminare definitivamente il copione «$1» con tutte le versioni?'] },
  { re: /^Die gesamte Historie von „(.+)" löschen\? Der aktuelle Text bleibt erhalten\.$/, to: ['Clear the entire history of “$1”? The current text is kept.', "Effacer tout l'historique de « $1 » ? Le texte actuel est conservé.", '¿Borrar todo el historial de «$1»? El texto actual se conserva.', 'Cancellare tutta la cronologia di «$1»? Il testo attuale resta.'] },
  { re: /^Eintrag vom (.+) löschen$/, to: ['Delete the entry from $1', "Supprimer l'entrée du $1", 'Borrar la entrada del $1', 'Elimina la voce del $1'] },
  { re: /^(.+) verwalten$/, to: ['Manage $1', 'Gérer $1', 'Gestionar $1', 'Gestisci $1'] },
  { re: /^Mikrofonfehler: (.+)$/, to: ['Microphone error: $1', 'Erreur de microphone : $1', 'Error del micrófono: $1', 'Errore del microfono: $1'] },
  { re: /^Fehler der Spracherkennung: (.+)$/, to: ['Speech recognition error: $1', 'Erreur de reconnaissance vocale : $1', 'Error de reconocimiento de voz: $1', 'Errore del riconoscimento vocale: $1'] },
  { re: /^Spracherkennung konnte nicht starten: (.+)$/, nested: true, to: ['Speech recognition could not start: $1', "La reconnaissance vocale n'a pas pu démarrer : $1", 'No se pudo iniciar el reconocimiento de voz: $1', 'Impossibile avviare il riconoscimento vocale: $1'] },
  { re: /^In der Gratisversion läuft der Text (\d+) Minuten pro Sitzung per Stimme mit\. Festes Tempo bleibt unbegrenzt\.$/, to: ['In the free edition the text follows your voice for $1 minutes per session. Fixed speed stays unlimited.', 'Dans la version gratuite, le texte suit votre voix pendant $1 minutes par session. La vitesse fixe reste illimitée.', 'En la versión gratis el texto sigue tu voz durante $1 minutos por sesión. La velocidad fija sigue siendo ilimitada.', 'Nella versione gratis il testo segue la voce per $1 minuti a sessione. La velocità fissa resta illimitata.'] },
];

// Beispieltexte je Sprache der Oberfläche.
export const SAMPLES = {
en: `Hello and welcome. It is good to have you with us today.

In the next few minutes I will show you how this teleprompter works. You speak quite normally, and the text follows at your pace.

When you pause, the text stops. When you speed up, it keeps up with you. You do not need to click or adjust anything.

Try it out: read this paragraph once slowly and once quickly. Feel free to skip a sentence. The prompter will find the place again.

Thank you for trying it out, and good luck with your next recording.`,
fr: `Bonjour et bienvenue. Nous sommes heureux de vous compter parmi nous aujourd'hui.

Dans les prochaines minutes, je vais vous montrer comment fonctionne ce prompteur. Vous parlez tout à fait normalement, et le texte suit votre rythme.

Quand vous faites une pause, le texte s'arrête. Quand vous accélérez, il vous suit. Vous n'avez rien à cliquer ni à régler.

Essayez: lisez ce paragraphe une fois lentement, puis une fois rapidement. N'hésitez pas à sauter une phrase. Le prompteur retrouvera l'endroit.

Merci de votre essai et bonne chance pour votre prochain enregistrement.`,
es: `Hola y bienvenidos. Nos alegra que hoy estén con nosotros.

En los próximos minutos les mostraré cómo funciona este teleprompter. Ustedes hablan con total normalidad y el texto avanza a su ritmo.

Cuando hacen una pausa, el texto se detiene. Cuando aceleran, los sigue. No tienen que hacer clic ni ajustar nada.

Pruébenlo: lean este párrafo una vez despacio y otra vez deprisa. Pueden saltarse una frase. El prompter volverá a encontrar el lugar.

Gracias por probarlo y mucho éxito en su próxima grabación.`,
it: `Buongiorno e benvenuti. Siamo felici di avervi con noi oggi.

Nei prossimi minuti vi mostrerò come funziona questo teleprompter. Parlate in modo del tutto normale e il testo segue il vostro ritmo.

Quando fate una pausa, il testo si ferma. Quando accelerate, vi segue. Non dovete fare clic né regolare nulla.

Provate: leggete questo paragrafo una volta lentamente e una volta velocemente. Saltate pure una frase. Il prompter ritroverà il punto.

Grazie per la prova e buona fortuna per la vostra prossima registrazione.`,
};
